const detect_mobi=(()=>{
// MOBI / AZW (Kindle / Mobipocket). Claim the extensions, and the PalmDB type/creator signature
// 'BOOKMOBI' (at offset 60) as a strong content signal for mis-named files.
function detect(intake) {
  if (hasExtension(intake, 'mobi', 'azw', 'azw3', 'prc')) return 0.95;
  const b = intake.bytes;
  if (b && b.length >= 68) {
    let sig = '';
    for (let i = 60; i < 68; i++) sig += String.fromCharCode(b[i]);
    if (sig === 'BOOKMOBI' || sig === 'TEXtREAd') return 0.6;
  }
  return 0;
}
return detect;
})();

const detect_lrf=(()=>{
// Sony LRF (BBeB / Broad Band eBook) — the old Sony Reader format. Detected by extension and its
// "L\0R\0F\0\0\0" magic. We don't decode the proprietary BBeB stream yet (see the renderer note),
// but recognizing it gives a clear message instead of a raw hex dump.
function detect(intake) {
  if (hasExtension(intake, 'lrf')) return 0.95;
  const b = intake.bytes;
  if (b && b.length >= 8 && b[0] === 0x4c && b[1] === 0x00 && b[2] === 0x52 && b[3] === 0x00 && b[4] === 0x46 && b[5] === 0x00) return 0.6;
  return 0;
}
return detect;
})();

const detect_mcp_config=(()=>{
function detect(intake) {
  if (intake.bytes?.[0] > 127) return 0; // not text
  const name = intake.filename?.toLowerCase() ?? '';
  const text = intake.textSample ?? '';

  // Exact known filenames → high confidence
  const MCP_NAMES = new Set(['mcp.json', '.mcp.json', 'claude_desktop_config.json', 'claude_code_config.json', 'claude.json']);
  if (MCP_NAMES.has(name)) {
    // Confirm it actually has mcpServers
    if (text.includes('"mcpServers"')) return 0.97;
    return 0.75; // filename match but maybe different format
  }

  // Any JSON with mcpServers key
  if (name.endsWith('.json') && text.includes('"mcpServers"')) return 0.85;
  if (text.includes('"mcpServers"') && text.includes('"command"')) return 0.80;

  return 0;
}
return detect;
})();

const detect_har=(()=>{
function detect(intake) {
  if (intake.isBinary) return 0;
  const text = (intake.text || '').trim();
  if (text.startsWith('{') && text.includes('"log"') && text.includes('"entries"')) {
    try {
      const obj = JSON.parse(text);
      if (obj?.log?.version && Array.isArray(obj.log.entries)) return 0.92;
    } catch {}
  }
  if (hasExtension(intake, 'har')) return 0.80;
  return 0;
}
return detect;
})();

const detect_jsonl=(()=>{
function detect(intake) {
  if (intake.isBinary) return 0;
  if (hasExtension(intake, 'jsonl', 'ndjson')) return 0.92;
  // Content heuristic: two separate JSON values on consecutive lines (don't fire on .json)
  if (!hasExtension(intake, 'json')) {
    const lines = (intake.text || '').split('\n').filter((l) => l.trim() && !l.trim().startsWith('#'));
    if (lines.length >= 2) {
      try {
        JSON.parse(lines[0]);
        JSON.parse(lines[1]);
        const s = lines[0].trim()[0];
        if (s === '{' || s === '[') return 0.55;
      } catch {}
    }
  }
  return 0;
}
return detect;
})();

